CREATE OR ALTER PROCEDURE [dbo].[uspSupplierIssue_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @SupplierId UNIQUEIDENTIFIER = NULL
	, @PurchaseOrderId UNIQUEIDENTIFIER = NULL
	, @GoodsReceiptId UNIQUEIDENTIFIER = NULL
	, @IssueType NVARCHAR(MAX) = NULL
	, @IssueStatus NVARCHAR(MAX) = NULL
	, @OwnerId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[SupplierId]
			, j1.[Name] AS [SupplierName]
			, t.[PurchaseOrderId]
			, j2.[PONo] AS [PurchaseOrderName]
			, t.[GoodsReceiptId]
			, j3.[ReceiptNo] AS [GoodsReceiptName]
			, t.[IssueType]
			, t.[Severity]
			, t.[Description]
			, t.[ReportedAt]
			, t.[DueAt]
			, t.[IssueStatus]
			, t.[Resolution]
			, t.[ClosedAt]
			, t.[OwnerId]
			, t.[CreatedDate]
		FROM [dbo].[SupplierIssue] AS t
		LEFT JOIN [dbo].[Supplier] AS j1 ON j1.[Id] = t.[SupplierId]
		LEFT JOIN [dbo].[PurchaseOrder] AS j2 ON j2.[Id] = t.[PurchaseOrderId]
		LEFT JOIN [dbo].[GoodsReceipt] AS j3 ON j3.[Id] = t.[GoodsReceiptId]
		WHERE 1 = 1
			AND (@SupplierId IS NULL OR t.[SupplierId] = @SupplierId)
			AND (@PurchaseOrderId IS NULL OR t.[PurchaseOrderId] = @PurchaseOrderId)
			AND (@GoodsReceiptId IS NULL OR t.[GoodsReceiptId] = @GoodsReceiptId)
			AND (ISNULL(@IssueType, '') = '' OR t.[IssueType] = @IssueType)
			AND (ISNULL(@IssueStatus, '') = '' OR t.[IssueStatus] = @IssueStatus)
			AND (@OwnerId IS NULL OR t.[OwnerId] = @OwnerId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'supplierId' THEN r.[SupplierId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'supplierId' THEN r.[SupplierId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'supplierName' THEN r.[SupplierName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'supplierName' THEN r.[SupplierName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'purchaseOrderId' THEN r.[PurchaseOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'purchaseOrderId' THEN r.[PurchaseOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'purchaseOrderName' THEN r.[PurchaseOrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'purchaseOrderName' THEN r.[PurchaseOrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'goodsReceiptId' THEN r.[GoodsReceiptId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'goodsReceiptId' THEN r.[GoodsReceiptId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'goodsReceiptName' THEN r.[GoodsReceiptName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'goodsReceiptName' THEN r.[GoodsReceiptName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'issueType' THEN r.[IssueType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'issueType' THEN r.[IssueType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'severity' THEN r.[Severity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'severity' THEN r.[Severity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'description' THEN r.[Description] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'description' THEN r.[Description] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'reportedAt' THEN r.[ReportedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'reportedAt' THEN r.[ReportedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dueAt' THEN r.[DueAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dueAt' THEN r.[DueAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'issueStatus' THEN r.[IssueStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'issueStatus' THEN r.[IssueStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'resolution' THEN r.[Resolution] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'resolution' THEN r.[Resolution] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'closedAt' THEN r.[ClosedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'closedAt' THEN r.[ClosedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'ownerId' THEN r.[OwnerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'ownerId' THEN r.[OwnerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
